  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('9'::bigint, 'reminder_offsets_days'::character varying(100), '2,4'::text, 'Reminder 1 and 2, as days after a cycle due_date. Reconstructed from the PPT user guide (fresher 32/34, experienced 62/64) — plan §2.3b. CONFIRM WITH HR.'::text, '2026-09-12 04:07:36.317487+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('10'::bigint, 'reminder_max_count'::character varying(100), '2'::text, 'Reminders per cycle before giving up.'::text, '2026-09-12 04:07:36.317487+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('11'::bigint, 'skip_weekends'::character varying(100), 'true'::text, 'Shift sends off Sat/Sun, as the original flow did.'::text, '2026-09-12 04:07:36.317487+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('12'::bigint, 'cc_emails'::character varying(100), 'qa.cc1@example.com;qa.cc2@example.com'::text, 'CC list, lifted from the scheduler flow where it was hardcoded. Now editable — that is the point.'::text, '2026-09-14 12:58:41.262+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('13'::bigint, 'hr_notification_emails'::character varying(100), 'qa.hr.notify@example.com'::text, 'Recipients of submit notifications and extend alerts (from the response flows).'::text, '2026-09-14 12:58:42.03+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('14'::bigint, 'sender_email'::character varying(100), ''::text, 'Shared mailbox once IT provisions it. Empty = fall back to MS_DEFAULT_SENDER_EMAIL (plan R16).'::text, '2026-09-12 04:07:36.317487+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('15'::bigint, 'reply_to_email'::character varying(100), ''::text, 'Reply-To so manager replies reach HR, not an unmonitored mailbox.'::text, '2026-09-12 04:07:36.317487+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('16'::bigint, 'token_validity_days'::character varying(100), '30'::text, 'Evaluation link lifetime.'::text, '2026-09-13 05:30:17.644+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('17'::bigint, 'shadow_mode'::character varying(100), 'false'::text, 'TRUE = write pea_email_log rows with status=suppressed instead of sending. This is the R6 stage-1 cutover check. MUST be set false to go live.'::text, '2026-09-14 15:47:41.682+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('18'::bigint, 'azure_scan_enabled'::character varying(100), 'false'::text, 'Master switch for the scheduled Entra intake scan. The manual "Scan now" button works regardless. Off by default — see plan §10: the New Joiner Inbox should land after the shadow-mode cutover, not during it.'::text, '2026-09-12 13:01:59.373152+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('19'::bigint, 'azure_scan_cron'::character varying(100), '0 9 * * *'::text, 'When the intake scan runs, in the scheduler timezone. 09:00 IST — two hours before the evaluation sweep, so a new joiner detected today is in the inbox before HR starts.'::text, '2026-09-12 13:01:59.373152+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('20'::bigint, 'azure_scan_window_days'::character varying(100), '45'::text, 'How far back to look for newly created Entra accounts. Wide enough to catch an account made before a delayed joining date, narrow enough that the first run does not enqueue four years of staff.'::text, '2026-09-12 13:01:59.373152+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('21'::bigint, 'azure_email_domain'::character varying(100), 'aapnainfotech.com'::text, 'Only accounts on this domain are considered joiners. Guests and resource accounts on other domains are ignored.'::text, '2026-09-12 13:01:59.373152+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('22'::bigint, 'rm_pl_map_seeded_at'::character varying(100), '2026-09-14T14:48:56.911Z'::text, 'Timestamp of the last RM→PL map seed from pea_employees. Blank until first run.'::text, '2026-09-14 14:48:56.911+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('23'::bigint, 'it_report_emails'::character varying(100), 'qa.it@example.com'::text, 'Where "Report to IT" messages go (semicolon-separated). Blank until IT names a distribution list. Outside production every message is redirected to the test inbox regardless.'::text, '2026-09-14 15:03:50.974+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('24'::bigint, 'confirmation_deadline_months'::character varying(100), '6'::text, 'Months from DOJ by which Confirmation Status must be filled in. Plan §2.7.'::text, '2026-09-13 03:36:25.234633+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('25'::bigint, 'confirmation_deadline_extended_months'::character varying(100), '8'::text, 'The same deadline once an extension has been granted. Plan §2.7.'::text, '2026-09-13 03:36:25.234633+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('26'::bigint, 'deadline_alert_email_enabled'::character varying(100), 'false'::text, 'Email HR a daily digest of probations past their confirmation deadline. Off until HR answers decision 17. The dashboard shows the list either way.'::text, '2026-09-14 14:16:06.273+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('27'::bigint, 'manager_link_validity_days'::character varying(100), '30'::text, 'How long a reporting manager''s "my team" link stays valid.'::text, '2026-09-13 03:36:25.234633+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('28'::bigint, 'azure_field_sync_enabled'::character varying(100), 'false'::text, 'Let the Entra scan overwrite an employee''s name and email with Entra''s values, except fields HR has locked (plan §6.5). Off by default: with it off the scan only records differences, so HR can see how many records would change before any do.'::text, '2026-09-13 03:36:25.234633+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
  INSERT INTO pea_settings (id, setting_key, setting_value, description, modified_at) VALUES ('45'::bigint, 'employee_self_view'::character varying(100), 'averages'::text, 'What an employee sees through their own link. off: nothing. schedule: dates and status only. averages: plus their average ratings. full: plus per-parameter ratings and manager comments. HR chose averages (13 Sep).'::text, '2026-09-14 14:18:43.977+00'::timestamp with time zone) ON CONFLICT DO NOTHING;
